import cpmpy as cp
import json
import numpy as np

# Input data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats

# Model definition
model = cp.Model()

# Decision Variables
is_host = cp.boolvar(shape=n_boats, name="is_host")  # Whether a boat is a host
visits = cp.boolvar(shape=(n_boats, n_boats, n_periods), name="visits")  # visits[i, j, t] is True if boat i visits boat j at time t

# Constraints
for j in range(n_boats):
    for t in range(n_periods):
        # Capacity constraint for each host boat at each time period
        model += cp.sum([crew_size[i] * visits[i, j, t] for i in range(n_boats) if i != j]) + crew_size[j] * is_host[j] <= capacity[j]

for i in range(n_boats):
    for j in range(n_boats):
        if i != j:
            # A guest boat cannot visit a non-host boat
            model += visits[i, j, :].sum() <= is_host[j]
            # A boat cannot visit itself
            model += visits[i, i, :].sum() == 0

for i in range(n_boats):
    for t in range(n_periods):
        # A boat can visit at most one host at a time
        model += cp.sum([visits[i, j, t] for j in range(n_boats) if i != j]) <= 1

for i in range(n_boats):
    for j in range(n_boats):
        if i != j:
            # A guest crew cannot meet more than once
            model += cp.sum([visits[i, j, t] for t in range(n_periods)]) <= 1

for i in range(n_boats):
    for j1 in range(n_boats):
        for j2 in range(j1 + 1, n_boats):
            if i != j1 and i != j2:
                # Guest crews cannot meet more than once across all hosts
                model += cp.sum([visits[i, j1, t] & visits[i, j2, t] for t in range(n_periods)]) == 0

# Objective: Minimize the number of host boats
model.minimize(cp.sum(is_host))

# Solve and print
if model.solve():
    solution = {
        'visits': visits.value().tolist(),
        'is_host': is_host.value().tolist()
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
